var data=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("Assets/Temp/MountainPassRefinement~/Test_StepGeometry.json"));var leftPoints=new Vector3[data.Count];var rightPoints=new Vector3[data.Count];for(int i=0;i<data.Count;i++){var d=data[i];var center=new Vector3((float)d["center"][0],(float)d["center"][1],(float)d["center"][2]);var right=new Vector3((float)d["right"][0],0,(float)d["right"][2]);float left=-1000,rightWidth=1000;for(int j=Mathf.Max(0,i-1);j<=Mathf.Min(data.Count-1,i+1);j++){left=Mathf.Max(left,(float)data[j]["left"]);rightWidth=Mathf.Min(rightWidth,(float)data[j]["rightWidth"]);}leftPoints[i]=center+right*(left+.15f);rightPoints[i]=center+right*(rightWidth-.15f);}
var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);var cubeMesh=cube.GetComponent<MeshFilter>().sharedMesh;UnityEngine.Object.DestroyImmediate(cube);var safety=GameObject.Find("ApproachSafetyWalls").transform;var lanterns=GameObject.Find("ApproachLanterns").transform;
for(int side=0;side<2;side++){var points=side==0?leftPoints:rightPoints;var combined=new System.Collections.Generic.List<CombineInstance>();for(int i=0;i<points.Length-1;i++){var difference=points[i+1]-points[i];var horizontal=difference;horizontal.y=0;combined.Add(new CombineInstance{mesh=cubeMesh,transform=Matrix4x4.TRS((points[i]+points[i+1])*.5f+Vector3.up*.35f,Quaternion.LookRotation(difference,Vector3.up),new Vector3(.36f,.7f,difference.magnitude+.16f))});var wall=safety.Find((side==0?"LeftSafety_":"RightSafety_")+i.ToString("00"));wall.SetPositionAndRotation((points[i]+points[i+1])*.5f+Vector3.up*1.65f,Quaternion.LookRotation(horizontal));wall.GetComponent<BoxCollider>().size=new Vector3(.42f,3.8f+Mathf.Abs(difference.y),horizontal.magnitude+.32f);}
var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Proto/MountainPass/Environment/"+(side==0?"ApproachLeftParapet":"ApproachRightParapet")+".asset");mesh.Clear();mesh.CombineMeshes(combined.ToArray());mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);for(int step=2;step<data.Count;step+=9)lanterns.Find((side==0?"LeftLantern_":"RightLantern_")+step.ToString("00")).position=points[step]+Vector3.up*.72f;}
AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return true;
